<?php
declare(strict_types=1);
namespace ReadyFinance;
final class FundService {
 public function __construct(private Core $c){}
 public function create(int $h,int $u,array $p,string $uuid):void {
  $c=$this->c;$row=['uuid'=>$uuid,'household_id'=>$h];
  $a=$c->scope('accounts',$p['account_uuid']??'',$h);if(!$a['active'])throw new Fault('Restore this account before creating a goal.');if($a['type']==='credit_card')throw new Fault('Use a cash or bank account to back this goal.');$purpose=$p['purpose']??'goal';if(!in_array($purpose,['goal','sinking_fund'],true))throw new Fault('Choose a supported fund type.');$c->insert('funds',$row+['name'=>Core::text($p['name']??''),'purpose'=>$purpose,'target'=>Core::money($p['target']??''),'target_date'=>empty($p['target_date'])?null:Core::date($p['target_date']),'account_id'=>$a['id'],'created_at'=>Core::now()]);
 }
 public function reserve(int $h,int $u,array $p,string $key):array{
  return $this->c->atomic(function()use($h,$u,$p,$key){$c=$this->c;$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$f=$c->scope('funds',$p['fund_uuid']??'',$h,true);$old=$c->one('SELECT fund_id,amount FROM fund_allocations WHERE household_id=? AND source_key=?',[$h,$key]);$a=Core::money($p['amount']??'');if(($p['action']??'reserve')==='release')$a=bcsub('0',$a,6);if($old){if($old['fund_id']!==$f['id']||bccomp($old['amount'],$a,6)!==0)throw new Fault('Command key conflict.',409);return ['saved'=>true];}if(!empty($f['archived']))throw new Fault('Restore this deleted goal before reserving money.');$acct=$c->one('SELECT ledger_id,active FROM accounts WHERE household_id=? AND id=?',[$h,$f['account_id']]);if(($p['action']??'reserve')!=='release'&&!$acct['active'])throw new Fault('Restore this account before reserving money.');$reserved=(string)$c->query('SELECT COALESCE(SUM(fa.amount),0) FROM fund_allocations fa JOIN funds f ON f.id=fa.fund_id WHERE f.household_id=? AND f.account_id=?',[$h,$f['account_id']])->fetchColumn();$own=(string)$c->query('SELECT COALESCE(SUM(amount),0) FROM fund_allocations WHERE household_id=? AND fund_id=?',[$h,$f['id']])->fetchColumn();if(bccomp(bcadd($own,$a,6),'0',6)<0)throw new Fault('Release cannot exceed the amount reserved.');if(bccomp($a,'0',6)>0&&bccomp(bcadd($reserved,$a,6),$c->balance($h,(int)$acct['ledger_id']),6)>0)throw new Fault('This account does not have enough unreserved money.');$c->insert('fund_allocations',['household_id'=>$h,'fund_id'=>$f['id'],'amount'=>$a,'source_key'=>$key,'created_at'=>Core::now()]);if((new PlanManagementService($c))->ready())$c->query('UPDATE funds SET row_version=row_version+1,updated_at=UTC_TIMESTAMP(6) WHERE household_id=? AND id=?',[$h,$f['id']]);$c->audit($h,$u,'fund.reserved',$f['uuid'],['amount'=>$a]);return ['saved'=>true];});
 }
}
